// The WhatsApp Trigger emits one item per webhook change: change.value plus `field`.
// Only `messages` changes that actually carry inbound messages continue. Status updates
// (sent/delivered/read/failed of outbound messages) contain `statuses`, not `messages`,
// and are not inbound messages, so they end here.
const out = [];
for (const item of $input.all()) {
  const value = item.json || {};
  if (value.field !== 'messages' || value.messages === undefined) continue;

  const metadata = value.metadata && typeof value.metadata === 'object' ? value.metadata : {};
  const contacts = Array.isArray(value.contacts) ? value.contacts : [];

  if (!Array.isArray(value.messages) || value.messages.length === 0) {
    // Malformed change: keep the whole value so the rejection is recorded with its payload.
    out.push({ json: { value_error: 'malformed_messages', metadata, contacts, message: null, value } });
    continue;
  }

  // One Meta webhook can batch several messages; each is ingested independently.
  for (const message of value.messages) {
    out.push({ json: { value_error: null, messaging_product: value.messaging_product ?? null, metadata, contacts, message } });
  }
}
return out;

// Maps one Meta WhatsApp Cloud API message to the provider-neutral event accepted by
// Supabase public.ingest_whatsapp_message(p_event). No business decisions happen here:
// routing, sender resolution, idempotency and sessions are decided in the database.
//
// Identity (Cloud API, 2026): a sender is identified by the business-scoped user id (BSUID,
// messages[].from_user_id / contacts[].user_id, e.g. "AM.1349…"). The phone number (from / wa_id)
// may be omitted, and `from` may itself carry a BSUID. Profile names are display text only and
// are never used for identity. group_id is passed through for group messages (not processed yet).
const KNOWN = ['text', 'image', 'document', 'video', 'audio', 'sticker', 'location', 'contacts',
  'interactive', 'button', 'reaction', 'order', 'system'];
const MEDIA = ['image', 'video', 'audio', 'document', 'sticker'];
const PHONE = /^[1-9][0-9]{6,14}$/;
const BSUID = /^[A-Z]{2}\.[A-Za-z0-9]{1,128}$/;

const src = $json;
const isObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const text = (v) => (typeof v === 'string' && v.trim() !== '' ? v.trim() : null);

const m = isObject(src.message) ? src.message : null;
const from = m ? text(m.from) : null;
const fromUserId = m ? text(m.from_user_id) : null;
const contacts = Array.isArray(src.contacts) ? src.contacts : [];
const contact =
  contacts.find((c) => isObject(c) && ((from && c.wa_id === from) || (fromUserId && c.user_id === fromUserId))) ||
  (contacts.length === 1 && isObject(contacts[0]) ? contacts[0] : null);

const contactWaId = text(contact?.wa_id);
const senderPhone = from && PHONE.test(from) ? from : contactWaId && PHONE.test(contactWaId) ? contactWaId : null;
const senderUserId = fromUserId ?? text(contact?.user_id) ?? (from && BSUID.test(from) ? from : null);

const providerType = m ? text(m.type) : null;
const type = KNOWN.includes(providerType) ? providerType : 'unsupported';
const part = m && providerType && isObject(m[providerType]) ? m[providerType] : {};

let body = null;
if (type === 'text') body = text(part.body);
else if (type === 'image' || type === 'video' || type === 'document') body = text(part.caption);
else if (type === 'button') body = text(part.text);
else if (type === 'interactive') body = text(part.button_reply?.title) ?? text(part.list_reply?.title);
else if (type === 'reaction') body = text(part.emoji);
else if (type === 'location') body = [text(part.name), text(part.address)].filter(Boolean).join(', ') || null;

// Media: metadata/reference only. Nothing is downloaded in this phase.
const media = MEDIA.includes(type) && (typeof part.id === 'string' || typeof part.id === 'number')
  ? { provider_media_id: String(part.id), mime_type: text(part.mime_type), filename: text(part.filename) }
  : null;

// Meta sends unix seconds as a string.
const tsRaw = m ? String(m.timestamp ?? '') : '';
const providerTimestamp = /^[0-9]{9,11}$/.test(tsRaw) ? new Date(Number(tsRaw) * 1000).toISOString() : null;

// Raw payload: the provider's own shape narrowed to this message. Temporary media URLs are dropped.
let rawMessage = m;
if (m && providerType && isObject(m[providerType]) && 'url' in m[providerType]) {
  const cleanPart = { ...m[providerType] };
  delete cleanPart.url;
  rawMessage = { ...m, [providerType]: cleanPart };
}
const rawPayload = src.value ?? {
  messaging_product: src.messaging_product ?? null,
  metadata: src.metadata ?? {},
  contacts: contact ? [contact] : [],
  messages: rawMessage ? [rawMessage] : [],
  field: 'messages',
};

let normalizationError = src.value_error || null;
if (!normalizationError && !m) normalizationError = 'malformed_message';

return {
  json: {
    event: {
      schema_version: 2,
      provider: 'whatsapp_cloud',
      normalization_error: normalizationError,
      recipient_phone_number_id: text(String(src.metadata?.phone_number_id ?? '')),
      provider_message_id: m ? text(m.id) : null,
      sender_user_id: senderUserId,
      sender_phone: senderPhone,
      sender_wa_id: from,
      sender_name: text(contact?.profile?.name),
      group_id: m ? text(m.group_id) : null,
      provider_timestamp: providerTimestamp,
      provider_message_type: providerType,
      message_type: type,
      text_body: body,
      context_provider_message_id: m ? text(m.context?.id) : null,
      media,
      raw_payload: rawPayload,
    },
  },
};
